-- MT2009_PLUS_GLOBAL_PROTO_V1: the fixed item bonuses of M2_BONUS_MODE=global (made by
-- tools/protoglobal/gen_item_proto_global.py from Owsap's official item_proto - do not edit by hand).
-- 390 items (armour and weapons that are the same item in both: type, subtype, level, refine step).
-- Only the table of the global values; apply.sh switches world.item_proto with it (global: writes these
-- applies and keeps the mt2009 ones in world.item_proto_apply_mt2009; mt2009: puts those back).
CREATE TABLE IF NOT EXISTS world.item_proto_apply_global (vnum INT UNSIGNED NOT NULL PRIMARY KEY,
  type TINYINT NOT NULL, subtype TINYINT NOT NULL, limitvalue0 INT NOT NULL,
  applytype0 TINYINT UNSIGNED NOT NULL, applyvalue0 INT NOT NULL,
  applytype1 TINYINT UNSIGNED NOT NULL, applyvalue1 INT NOT NULL,
  applytype2 TINYINT UNSIGNED NOT NULL, applyvalue2 INT NOT NULL) ENGINE=InnoDB;
START TRANSACTION;
DELETE FROM world.item_proto_apply_global;
COMMIT;
